sop:
@f1 w.request.filler text=just
@f2 w.request.filler text=just
@r1 w.request.request act=change mood=do words="i want a desert oasis at sunset" predicate=want
@r1.t w.request.target request=$r1 family=page mode=existing determiner=definite fill=context
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=page.time value=sunset words="at sunset" operator=eq phase=result
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=page.scene value="desert oasis" words="a desert oasis" operator=eq phase=result
@r2 w.request.request act=make mood=do words="a medium orange fire just next to the tent"
@r2.t w.request.target request=$r2 family=drawn mode=new determiner=indefinite sort=fire
@r2.c1 w.request.constraint request=$r2 on=size attribute=drawn.size value=medium operator=degree phase=result
@r2.c2 w.request.constraint request=$r2 on=attribute attribute=drawn.colour value=orange operator=eq phase=result
@r2.c3 w.request.constraint request=$r2 on=place attribute=drawn.relation value="next to" words="next to the tent" operator=relation phase=result open_value=true
@r2.c4 w.request.constraint request=$r2 on=place attribute=drawn.anchor value="the tent" operator=relation phase=selector
@r3 w.request.request act=make mood=do words="behind the tent, two large brown camels"
@r3.t w.request.target request=$r3 family=drawn mode=new determiner=quantified sort=camel sort_words=camels
