@r3.c4 w.request.constraint request=$r3 on=place attribute=drawn.relation value=behind words="behind the tent" operator=relation phase=result
@r3.c5 w.request.constraint request=$r3 on=place attribute=drawn.anchor value="the tent" operator=relation phase=selector
@r4 w.request.request act=make mood=do words="a medium traveler sitting right next to the fire"
@r4.t w.request.target request=$r4 family=drawn mode=new determiner=indefinite sort=traveler
@r4.c1 w.request.constraint request=$r4 on=size attribute=drawn.size value=medium operator=degree phase=result
